content.text:
请对以下 case 进行三维加权评分。

=== case_id ===
Case-26-group-buy-010

=== 用户原始指令 (query.txt) ===
缺口人数实时变，点进是找人页，能读日程看时间，已拼成有显示

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "缺口人数实时变，点进是找人页，能读日程看时间，已拼成有显示",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.example.groupbuy",
        "abilityName": "com.example.groupbuy.FindPeopleAbility",
        "uri": "groupbuy://find-people"
      }
    }
  ],
  "dataModelSchema": {
    "groupBuy": {
      "gapText": {
        "type": "string",
        "description": "拼单当前缺口人数展示文本，成团后可更新为已满员等状态文本。",
        "sampleValue": "缺2人"
      },
      "statusText": {
        "type": "string",
        "description": "拼单成团状态短文本，例如待成团或已拼成。",
        "sampleValue": "待成团"
      },
      "actionText": {
        "type": "string",
        "description": "进入找人页的动作短文本。",
        "sampleValue": "找人拼单"
      }
    },
    "data": {
      "calendar": {
        "items": [
          {
            "dtStart": {
              "type": "string",
              "description": "日程起始时间，用于判断适合找人拼单的时间。",
              "sampleValue": "19:30"
            },
            "dtEnd": {
              "type": "string",
              "description": "日程结束时间，用于展示可约时间段。",
              "sampleValue": "20:00"
            }
          }
        ]
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/person_3_fill.svg",
      "description": "三人组实心图标，适合表示拼单群组、找人补位和团购成员状态。"
    }
  ]
}

